#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "scaled_masked_softmax_v2_tiling.h"
extern "C" void sms_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace sms_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_scaled_masked_softmax_v2(const at::Tensor &qk, const at::Tensor &mask, double scale) {
    TORCH_CHECK(qk.dim()==4,"qk must be [B,N,S,S]"); TORCH_CHECK(qk.scalar_type()==at::kHalf,"fp16 only");
    TORCH_CHECK(qk.is_contiguous()&&mask.is_contiguous(),"must be contiguous");
    const auto M=static_cast<int32_t>(qk.numel()/qk.sizes()[3]), N=static_cast<int32_t>(qk.sizes()[3]);
    // Broadcast mask to match qk if needed
    auto mask_bc = mask.expand_as(qk).contiguous();
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty_like(qk);
    at::Tensor tc=at::empty({static_cast<long>(sizeof(SMSKernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<SMSKernelTiling*>(tc.data_ptr());
    t->M=M; t->N=N; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc; t->scale=static_cast<float>(scale);
    auto tn=tc.to(at::kPrivateUse1);
    auto stm=c10_npu::getCurrentNPUStream().stream(false);
    sms_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(qk.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(mask_bc.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_sms_ext, m) { m.def("run_scaled_masked_softmax_v2",&sms_ext::run_scaled_masked_softmax_v2,""); }

