extern "C" __global__ __aicore__ void sms_custom_fp16(GM_ADDR qk,GM_ADDR mask,GM_ADDR y,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    SMSKernel<half> k; k.Init(qk,mask,y,t,&p); k.Process();
}
extern "C" void sms_do_fp16(uint32_t d,void* s,uint8_t* qk,uint8_t* mask,uint8_t* y,uint8_t* t){
    sms_custom_fp16<<<d,nullptr,s>>>(qk,mask,y,t);
}

