#pragma once
#ifndef SMS_KERNEL_H
#define SMS_KERNEL_H
#include "kernel_operator.h"
#include "kernel_common.h"
#include "scaled_masked_softmax_v2_tiling.h"

constexpr float NEG_INF = -1.0e9f;

template <typename T>
class SMSKernel {
public:
    __aicore__ inline void Init(GM_ADDR qk, GM_ADDR mask, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);
        qkGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(qk), tiling_.M * tiling_.N);
        maskGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(mask), tiling_.M * tiling_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.M * tiling_.N);
        if ASCEND_IS_AIV {
            pipe_ = pipe; subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(qkInQ_, 1, tiling_.N * sizeof(T));
            pipe_->InitBuffer(maskInQ_, 1, tiling_.N * sizeof(T));
            pipe_->InitBuffer(yOutQ_, 1, tiling_.N * sizeof(T));
            if constexpr (!std::is_same_v<T, float>) {
                pipe_->InitBuffer(w1_, tiling_.N * sizeof(float));
                pipe_->InitBuffer(w2_, tiling_.N * sizeof(float));
            }
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tiling_.tasksPerCore; ++li) {
                const int bx = ci * tiling_.tasksPerCore + li;
                if (bx >= BlockCount()) continue;
                for (int r = 0; r < subBlockRows_; ++r) {
                    const int ri = bx * tiling_.blockM + si * subBlockRows_ + r;
                    if (ri < tiling_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM; }
    __aicore__ inline void CopyIn(int32_t ri) {
        qkInQ_.AllocTensor<T>(qkL_); AscendC::DataCopy(qkL_, qkGM_[ri * tiling_.N], tiling_.N); qkInQ_.EnQue(qkL_);
        maskInQ_.AllocTensor<T>(maskL_); AscendC::DataCopy(maskL_, maskGM_[ri * tiling_.N], tiling_.N); maskInQ_.EnQue(maskL_);
    }
    __aicore__ inline void CopyOut(int32_t ri) {
        yOutQ_.DeQue<T>(yL_); AscendC::DataCopy(yGM_[ri * tiling_.N], yL_, tiling_.N); yOutQ_.FreeTensor(yL_);
    }
    __aicore__ inline void ComputeRow(int32_t ri) {
        qkInQ_.DeQue<T>(qkL_); maskInQ_.DeQue<T>(maskL_); yOutQ_.AllocTensor<T>(yL_);

        if constexpr (std::is_same_v<T, float>) {
            auto qkFp32 = qkL_.template ReinterpretCast<float>();
            auto maskFp32 = maskL_.template ReinterpretCast<float>();
            auto yFp32 = yL_.template ReinterpretCast<float>();

            // Scale and mask (scalar loop — no math.h calls)
            for (int32_t i = 0; i < tiling_.N; ++i) {
                float v = qkFp32(i) * tiling_.scale;
                yFp32(i) = (maskFp32(i) == 0.0f) ? NEG_INF : v;
            }
            // Find max (scalar)
            float maxVal = yFp32(0);
            for (int32_t i = 1; i < tiling_.N; ++i) { float v = yFp32(i); if (v > maxVal) maxVal = v; }
            // Subtract max (vector)
            AscendC::Adds(yFp32, yFp32, -maxVal, tiling_.N);
            // Exp (vector)
            AscendC::Exp(yFp32, yFp32, tiling_.N);
            // Sum (scalar)
            float sumVal = 0.0f;
            for (int32_t i = 0; i < tiling_.N; ++i) sumVal += yFp32(i);
            // Divide (vector)
            AscendC::Muls(yFp32, yFp32, 1.0f / sumVal, tiling_.N);
        } else {
            auto qkFp32 = w1_.Get<float>();
            auto maskFp32 = w2_.Get<float>();
            AscendC::Cast(qkFp32, qkL_, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::Cast(maskFp32, maskL_, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();

            // Scale and mask (scalar)
            for (int32_t i = 0; i < tiling_.N; ++i) {
                float v = qkFp32(i) * tiling_.scale;
                qkFp32(i) = (maskFp32(i) == 0.0f) ? NEG_INF : v;
            }
            // Softmax
            float maxVal = qkFp32(0);
            for (int32_t i = 1; i < tiling_.N; ++i) { float v = qkFp32(i); if (v > maxVal) maxVal = v; }
            AscendC::Adds(qkFp32, qkFp32, -maxVal, tiling_.N);
            AscendC::Exp(qkFp32, qkFp32, tiling_.N);
            float sumVal = 0.0f;
            for (int32_t i = 0; i < tiling_.N; ++i) sumVal += qkFp32(i);
            AscendC::Muls(qkFp32, qkFp32, 1.0f / sumVal, tiling_.N);

            AscendC::Cast(yL_, qkFp32, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
        }
        yOutQ_.EnQue(yL_); qkInQ_.FreeTensor(qkL_); maskInQ_.FreeTensor(maskL_);
    }
    __aicore__ inline void ProcessRow(int ri) { CopyIn(ri); ComputeRow(ri); CopyOut(ri); }
private:
    SMSKernelTiling tiling_{}; AscendC::TPipe *pipe_{}; int subBlockRows_{};
    AscendC::GlobalTensor<T> qkGM_, maskGM_, yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN,0> qkInQ_, maskInQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT,0> yOutQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> w1_, w2_;
    AscendC::LocalTensor<T> qkL_, maskL_, yL_;
};
#endif

